// The mappings file's JSON Schema (schema/freewheel-mappings.schema.json,
// generated by crates/freewheel-core mappings_file/schema.rs) checked with
// ajv, as editors use it: the valid fixtures, the examples in SCHEMA.md and
// the file export writes pass; every invalid fixture fails. The Rust parser
// reads the same fixtures (mappings_file tests), so the two agree.
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import Ajv2020 from "ajv/dist/2020.js";
import { describe, expect, test } from "vitest";

const root = new URL("..", import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1");
const schema = JSON.parse(readFileSync(join(root, "schema/freewheel-mappings.schema.json"), "utf8"));
const validate = new Ajv2020({ allErrors: true, strict: true, allowMatchingProperties: true }).compile(schema);
const fixtures = (sub) =>
  readdirSync(join(root, "schema/fixtures", sub))
    .filter((f) => f.endsWith(".json"))
    .map((f) => [f, JSON.parse(readFileSync(join(root, "schema/fixtures", sub, f), "utf8"))]);

test("the schema is draft 2020-12, published where export's $schema points", () => {
  expect(schema.$schema).toBe("https://json-schema.org/draft/2020-12/schema");
  expect(schema.$id).toBe("https://raw.githubusercontent.com/brinkercode/freewheel/main/schema/freewheel-mappings.schema.json");
  const exported = JSON.parse(readFileSync(join(root, "schema/fixtures/valid/exported-everything.json"), "utf8"));
  expect(exported.$schema).toBe(schema.$id);
});

describe("valid files pass", () => {
  test.each(fixtures("valid"))("%s", (_, file) => {
    expect(validate(file), JSON.stringify(validate.errors, null, 1)).toBe(true);
  });
});

describe("invalid files fail", () => {
  test.each(fixtures("invalid"))("%s", (_, file) => {
    expect(validate(file)).toBe(false);
  });
});

test("the full examples in SCHEMA.md pass", () => {
  const doc = readFileSync(join(root, "SCHEMA.md"), "utf8").replace(/\r\n/g, "\n");
  const files = doc
    .split("```json\n")
    .slice(1)
    .map((b) => b.split("\n```")[0])
    .filter((b) => b.startsWith('{\n  "$schema"'));
  expect(files.length).toBe(2);
  for (const text of files) expect(validate(JSON.parse(text)), JSON.stringify(validate.errors)).toBe(true);
});

test("editors can complete every key name on a page", () => {
  const keys = Object.keys(schema.$defs.page.properties);
  expect(keys.length).toBe(43);
  expect(keys).toContain("CAM1");
  expect(keys).toContain("STOP/PLAY");
  expect(schema.$defs.keyAction.examples).toContain("open Spotify");
});

test("each action form: the right spellings pass, near misses fail", () => {
  const page = (action) => ({ pages: { Main: { CUT: action } } });
  for (const ok of ["Ctrl+Z", "ctrl+shift+z", "Ctrl + Alt + Delete", "Win+PgDn", "Play/Pause", "Previous track", "F13", "Ctrl+/", "Ctrl++", "Ctrl+Plus",
    "hold Shift", "toggle Ctrl+Alt", "open Spotify", "open C:\\Tools\\a b.exe", "https://x.org", "page Music", "back", "scroll -100", "scroll up",
    "wheel volume", "wheel app volume", "wheel Brightness", "wheel mode shuttle", "nothing", null, { open: "x", args: ["a"], cwd: "~" }])
    expect(validate(page(ok)), `${JSON.stringify(ok)}: ${JSON.stringify(validate.errors?.[0])}`).toBe(true);
  for (const bad of ["", "Ctrl+", "Ctrl+Shift", "hold", "toggle Shift+", "scroll 101", "scroll", "wheel", "wheel louder", "pagee Music", "Ctrl+Zed", 1, [], { args: [] }, { open: "" }])
    expect(validate(page(bad)), JSON.stringify(bad)).toBe(false);
  expect(validate({ wheel: { jog: { left: "back" } } })).toBe(false);
});

test("the key names and their order are the app's own drawing's (src/assets/speed-editor.svg)", () => {
  const svg = readFileSync(join(root, "src/assets/speed-editor.svg"), "utf8");
  const drawn = [...svg.matchAll(/data-key="([^"]+)"/g)].map((m) => m[1]).filter((k) => k !== "WHEEL");
  expect(Object.keys(schema.$defs.page.properties).sort()).toEqual([...drawn].sort());
  // SCHEMA.md lists them in device order, as the drawing does.
  const doc = readFileSync(join(root, "SCHEMA.md"), "utf8");
  const listed = [...doc.matchAll(/^\| \d+ \| `([^`]+)` \|/gm)].map((m) => m[1]);
  expect(listed).toEqual(drawn);
});
